		try (InspectingCollectionFactory factory = new InspectingCollectionFactory()) {
			Set<BindingSet> persisted = factory.createSetOfBindingSets(context::createBindingSet, context::hasBinding,
					context::getValue, context::setBinding);
			for (BindingSet row : expected) {
				assertTrue(persisted.add(row));
			}
			assertEquals(32, factory.diskSetSize(), "exercise BindingSetSerializer in a real spilled collection");
			assertEquals(expected.size(), persisted.size());
			for (BindingSet restored : persisted) {
				BindingSet original = expectedById.get(restored.getValue("id"));
				assertNotNull(original);
				assertLogicalDomain(original, restored);
			}
			for (BindingSet row : expected) {
				assertFalse(persisted.add(context.createBindingSet(row)), "persisted logical keys must deduplicate");
			}
			assertEquals(expected.size(), persisted.size());
			assertEquals(expected.size(), factory.diskSetSize());
		}
