	@Test
	void distinctKeysSpillAndDeduplicateMixedBindingSetImplementations() {
		List<BindingSet> expected = new ArrayList<>();
		for (int i = 0; i < 48; i++) {
			Value value = i % 2 == 0 ? VF.createIRI("urn:spill:" + i) : VF.createLiteral(i);
			expected.add(copyAs(row("s", value, "o", value), i % 3));
		}
		MapBindingSet implementationSpecific = new MapBindingSet();
		implementationSpecific.addBinding(new SimpleBinding("s", VF.createIRI("urn:binding-state")) {
			private static final long serialVersionUID = 1L;
			@SuppressWarnings("unused")
			private final Object implementationState = new Object();
		});
		expected.add(implementationSpecific);
		Value value = VF.createIRI("urn:partial");
		expected.add(row("s", value));
		expected.add(copyAs(row("o", value), 1));
		expected.add(copyAs(new MapBindingSet(), 2));
		expected.add(row("s", value, "o", value, "extra", VF.createLiteral("extra")));

		List<BindingSet> input = new ArrayList<>(expected);
		// Probe every key through all three implementations only after all unique rows have spilled.
		for (BindingSet original : expected) {
			for (int implementation = 0; implementation < 3; implementation++) {
				input.add(copyAs(original, implementation));
			}
		}

		SingletonSet child = new SingletonSet();
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				return new CloseableIteratorIteration<>(Collections.emptyIterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null) {
			@Override
			public QueryEvaluationStep precompile(TupleExpr expr, QueryEvaluationContext context) {
				if (expr == child) {
					// Keep the original heterogeneous rows: VALUES normalization would hide this coverage.
					return bindings -> new CloseableIteratorIteration<>(input.iterator());
				}
				return super.precompile(expr, context);
			}
		};
		InspectingCollectionFactory factory = new InspectingCollectionFactory();
		strategy.setCollectionFactory(() -> factory);
		try (CloseableIteration<BindingSet> result = strategy
				.precompile(new Distinct(child), new QueryEvaluationContext.Minimal(null))
				.evaluate(EmptyBindingSet.getInstance())) {
			for (int i = 0; i < expected.size(); i++) {
				assertTrue(result.hasNext());
				assertSame(expected.get(i), result.next(), "DISTINCT must return the original first row");
				if (i == 31) {
					assertEquals(32, factory.diskSetSize(), "a named MapDB set must actually contain the keys");
				}
			}
			assertEquals(expected.size(), factory.diskSetSize());
			assertFalse(result.hasNext(), "cross-implementation duplicates must survive disk round trips");
		}
		assertTrue(factory.isDatabaseClosed(), "DISTINCT must close its spill database");
	}

	private enum CallbackFailure {
		QUERY_INTERRUPTED,
		QUERY_EVALUATION,
		ASSERTION,
		OTHER_RUNTIME,
		OTHER_ERROR;

		Throwable failure() {
			return switch (this) {
			case QUERY_INTERRUPTED -> new QueryInterruptedException("retained interruption");
			case QUERY_EVALUATION -> new QueryEvaluationException("retained query failure");
			case ASSERTION -> new AssertionError("retained callback assertion");
			case OTHER_RUNTIME -> new IllegalStateException("retained runtime failure");
			case OTHER_ERROR -> new Error("retained callback error");
			};
		}
	}

	private static void throwCallbackFailure(Throwable failure) {
		if (failure instanceof RuntimeException runtime) {
			throw runtime;
		}
		throw (Error) failure;
	}

	private static ArrayBindingBasedQueryEvaluationContext arrayContext() {
		return new ArrayBindingBasedQueryEvaluationContext(new QueryEvaluationContext.Minimal(null),
				new String[] { "id", "x", "y" }, null);
	}

	private static QueryBindingSet logicalRow(Object... bindings) {
		QueryBindingSet result = new QueryBindingSet();
		for (int i = 0; i < bindings.length; i += 2) {
			result.setBinding((String) bindings[i], (Value) bindings[i + 1]);
		}
		return result;
	}

	private static void assertLogicalDomain(BindingSet expected, BindingSet actual) {
		assertEquals(expected.getBindingNames(), actual.getBindingNames());
		assertEquals(expected.size(), actual.size());
		assertEquals(expected, actual);
		assertEquals(actual, expected);
		assertEquals(expected.hashCode(), actual.hashCode());
		for (String name : expected.getBindingNames()) {
			assertTrue(actual.hasBinding(name));
			assertEquals(expected.getValue(name), actual.getValue(name));
			if (expected.getValue(name) == null) {
				assertNull(actual.getBinding(name));
			}
		}
		for (Binding binding : actual) {
			assertNotNull(binding);
			assertNotNull(binding.getValue(), "logical null shadows must never become RDF bindings");
		}
	}

	private static DefaultEvaluationStrategy distinctStrategy(SingletonSet child, List<BindingSet> input,
			InspectingCollectionFactory factory) {
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				return new CloseableIteratorIteration<>(Collections.emptyIterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null) {
			@Override
			public QueryEvaluationStep precompile(TupleExpr expr, QueryEvaluationContext context) {
				return expr == child ? bindings -> new CloseableIteratorIteration<>(input.iterator())
						: super.precompile(expr, context);
			}
		};
		strategy.setCollectionFactory(() -> factory);
		return strategy;
	}

	private static BindingSet copyAs(BindingSet original, int implementation) {
		List<String> names = new ArrayList<>();
		List<Value> values = new ArrayList<>();
		for (Binding binding : original) {
			names.add(binding.getName());
			values.add(binding.getValue());
		}
		Collections.reverse(names);
		Collections.reverse(values);
		if (implementation == 0) {
			MapBindingSet copy = new MapBindingSet();
			for (int i = 0; i < names.size(); i++) {
				copy.addBinding(names.get(i), values.get(i));
			}
			return copy;
		}
		names.add("unbound");
		values.add(null);
		if (implementation == 1) {
			return new ListBindingSet(names, values);
		}
		ArrayBindingSet copy = new ArrayBindingSet(names.toArray(String[]::new));
		for (int i = 0; i < names.size(); i++) {
			copy.getDirectSetBinding(names.get(i)).accept(values.get(i), copy);
		}
		return copy;
	}

	private static MapBindingSet row(Object... bindings) {
		MapBindingSet result = new MapBindingSet();
		for (int i = 0; i < bindings.length; i += 2) {
			result.addBinding((String) bindings[i], (Value) bindings[i + 1]);
		}
		return result;
	}

	private static final class InspectingCollectionFactory extends MapDb3CollectionFactory {
		private InspectingCollectionFactory() {
			super(1);
		}

		private Serializer<BindingSet> bindingSetSerializer(QueryEvaluationContext context) {
			return createBindingSetSerializer(context::createBindingSet, context::hasBinding, context::getValue,
					context::setBinding);
		}

		private int diskSetSize() {
			int size = 0;
			if (db != null && !db.isClosed()) {
				for (Object collection : db.getAll().values()) {
					if (collection instanceof Set<?> set) {
						size = Math.max(size, set.size());
					}
				}
			}
			return size;
		}

		private boolean isDatabaseClosed() {
			return db != null && db.isClosed();
		}
	}
